package com.ruoyi.medical.workflow;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.medical.workflow.TaskCandidateAssemblyStageProtocolV1.*;
/** Deferred at the user's code-first request. Does not contact any service. */
class TaskCandidateAssemblyStageProtocolV1Test {
 static String id(int n){return String.format("00000000-0000-4000-8000-%012d",n);}static final String H="a".repeat(64);
 CommandV1 command(){return new CommandV1(new PreparedV1("1.0.0",id(1),id(2),H,id(3),H,H),id(4));}
 List<ArtifactV1> artifacts(){var result=new ArrayList<ArtifactV1>();for(int n=0;n<4;n++)result.add(new ArtifactV1(KINDS.get(n),id(10+n),H,"immutable-object-version-"+n,H));return result;}
 ProducedV1 produced(boolean ready){return new ProducedV1("1.0.0",command(),artifacts(),ready,ready?List.of():List.of("FACT_IMPACT_READ_REQUIRED"),false,false);}
 @Test void allFourPhysicalOriginalsAreRequired(){assertThrows(IllegalArgumentException.class,()->new ProducedV1("1.0.0",command(),artifacts().subList(0,3),true,List.of(),false,false));var duplicate=new ArrayList<>(artifacts());duplicate.set(3,duplicate.get(0));assertThrows(IllegalArgumentException.class,()->new ProducedV1("1.0.0",command(),duplicate,true,List.of(),false,false));}
 @Test void outputCannotClaimDocumentSavedOrN07(){assertThrows(IllegalArgumentException.class,()->new ProducedV1("1.0.0",command(),artifacts(),true,List.of(),true,false));assertThrows(IllegalArgumentException.class,()->new ProducedV1("1.0.0",command(),artifacts(),true,List.of(),false,true));}
 @Test void blockersNeverSatisfyStage(){assertFalse(new CommitV1("1.0.0",produced(false),id(20),H).satisfied());assertTrue(new CommitV1("1.0.0",produced(true),id(20),H).satisfied());assertThrows(IllegalArgumentException.class,()->new ProducedV1("1.0.0",command(),artifacts(),true,List.of("OPEN_CONFLICT"),false,false));}
 @Test void recoveryDoesNotManufactureCompletion(){assertThrows(IllegalArgumentException.class,()->new RecoveryV1("1.0.0","COMMITTED",command(),produced(true),null));assertThrows(IllegalArgumentException.class,()->new RecoveryV1("1.0.0","PRODUCED",command(),null,null));assertDoesNotThrow(()->new RecoveryV1("1.0.0","PENDING",command(),null,null));}
 @Test void exactWireRejectsExtraOrMissingFields()throws Exception{var schema=new TaskCandidateAssemblyStageSchemaV1();var ref=WorkflowOriginalRunningV2Test.reference(100000);var prepared=new PreparedV1("1.0.0",ref.runId(),id(2),H,id(3),H,H);var cmd=new CommandV1(prepared,id(4));var request=new TaskCandidateAssemblyStageSchemaV1.Request("1.0.0","RECOVER",ref,cmd,null);var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var wire=(com.fasterxml.jackson.databind.node.ObjectNode)mapper.readTree(schema.request(request));assertEquals(request,schema.read(mapper.writeValueAsBytes(wire)));wire.put("document_saved",true);assertThrows(Exception.class,()->schema.read(mapper.writeValueAsBytes(wire)));wire.remove("document_saved");wire.remove("produced");assertThrows(Exception.class,()->schema.read(mapper.writeValueAsBytes(wire)));}
 @Test void dispatchAndCommitCannotSwapCommands(){var first=produced(true);var other=new CommandV1(command().prepared(),id(44));assertThrows(IllegalArgumentException.class,()->new RecoveryV1("1.0.0","PRODUCED",other,first,null));}
 @Test void versionPinHasNoProfessionalExecutionAlias(){var extension=new CandidateAssemblyWorkflowExtensionV1("1.0.0",id(33),H,H,"medical.run.candidate-assembly.prepare.v1","medical.run.candidate-assembly.dispatch.v1","medical.run.candidate-assembly.commit.v1","medical.run.candidate-assembly.recover.v1",CandidateAssemblyWorkflowExtensionV1.MARKER);assertEquals(extension,CandidateAssemblyWorkflowExtensionV1.load(extension.canonical()));assertThrows(IllegalArgumentException.class,()->CandidateAssemblyWorkflowExtensionV1.load(extension.canonical().replace("medical.run.candidate-assembly.dispatch.v1","medical.professional.step.v2")));assertEquals(2,extension.memo().size());}
}
